SELECT count(*) AS row_count,(SELECT count(*) FROM pragma_table_info('t1')) AS column_count,sum(c00) AS sum_c00,sum(c62) AS sum_c62,sum(c63) AS sum_c63,sum(c64) AS sum_c64,sum(c65) AS sum_c65,sum(a) AS sum_a,sum(e) AS sum_e,(SELECT count(*) FROM pragma_index_info('t1x1')) AS t1x1_columns,(SELECT group_concat(name,',') FROM (SELECT name FROM pragma_index_info('t1x2') ORDER BY seqno)) AS t1x2_columns,(SELECT group_concat(name,',') FROM (SELECT name FROM pragma_index_info('t1cd') ORDER BY seqno)) AS t1cd_columns FROM t1